WITH scored AS (SELECT id, store_name, city, region, SUM(sqft) OVER (ORDER BY sqft ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) cumulative_sqft, FIRST_VALUE(region, TRUE) OVER (PARTITION BY city ORDER BY sqft ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) first_known_region FROM stores WHERE MONTH(opened_date) IN (2, 3, 10)) SELECT id, store_name, city, first_known_region FROM scored;
